import { fireEvent, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { renderWithProviders } from "@/test/render-with-providers";
import { contactService } from "../api/contact.service";
import { ContactForm } from "./contact-form";
const cases: [string, string, string, boolean][] = [
  ["CON-005", "fullName", "A", false],
  ["CON-006", "fullName", "AA", true],
  [
    "CON-007",
    "company",
    "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA",
    true,
  ],
  [
    "CON-008",
    "company",
    "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA",
    false,
  ],
  [
    "CON-009",
    "subject",
    "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA",
    true,
  ],
  [
    "CON-010",
    "subject",
    "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA",
    false,
  ],
  [
    "CON-011",
    "message",
    "",
    true,
  ],
  [
    "CON-012",
    "message",
    "",
    false,
  ],
];
const labels: Record<string, RegExp> = {
  fullName: /^Full name/,
  company: /^Company/,
  subject: /^Subject/,
  message: /^Your message/,
};
describe("Contact boundaries from the QA catalogue", () => {
  it.each(cases)("%s validates %s before calling the submit service", async (_id, field, value, valid) => {
    const submit = vi
      .spyOn(contactService, "submit")
      .mockResolvedValue({ reference: "MSG-QATEST01", status: "submitted" });
    renderWithProviders(<ContactForm initialType="general" />);
    fireEvent.change(screen.getByLabelText(/Full name/), { target: { value: "QA Tester" } });
    fireEvent.change(screen.getByLabelText(/Email address/), { target: { value: "qa@example.test" } });
    fireEvent.change(screen.getByLabelText(/Phone no/), { target: { value: "88009900" } });
    const label = labels[field];
    if (!label) throw new Error(`Missing label for ${field}`);
    const input = screen.getByRole("textbox", { name: label });
    fireEvent.change(input, { target: { value } });
    await userEvent.setup().click(screen.getByRole("button", { name: "Submit" }));
    if (valid) {
      await waitFor(() => expect(submit).toHaveBeenCalledOnce());
      expect(submit.mock.calls[0]?.[0].contact).toMatchObject({ [field]: value.trim() });
    } else {
      await waitFor(() => expect(input).toHaveAttribute("aria-invalid", "true"));
      expect(submit).not.toHaveBeenCalled();
    }
  });
});
